-- Seed convocatoria_content for torneoid=346 (LXX Torneo Anual Club de Golf Valle Alto 2026).
-- Source: official convocatoria PDF (valtoconvocatoria.pdf).
-- Safe to re-run: uses ON DUPLICATE KEY UPDATE on (torneoid, section_id).

INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled)
VALUES (346, 'descripcion', 'text', 'Descripción', '{"text": "Se convoca a todos los Asociados del Club de Golf Valle Alto e invitados, a participar en su LXX Torneo Anual de Invitación, que se llevará a cabo del 24 de abril al 02 de mayo de 2026 en las instalaciones de nuestro club.\\n\\nBases: podrán participar damas y caballeros amateurs mayores de 18 años que tengan hándicap registrado en la FMG o en el sistema interno del club, publicado al 1° de abril de 2026. En las categorías Campeonato y Premier se permitirá jugar a menores de 18 años que cuenten con el hándicap solicitado. Al jugador que no tenga hándicap registrado, los profesionales podrán calcularle uno siempre y cuando tenga un mínimo de 8 scores entregados."}', 1, 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  title        = VALUES(title),
  content      = VALUES(content),
  sort_order   = VALUES(sort_order),
  enabled      = VALUES(enabled);

INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled)
VALUES (346, 'elegibilidad', 'elegibilidad', 'Elegibilidad', '{"eligibilityText": "Damas y caballeros amateurs mayores de 18 años con hándicap registrado en la FMG o en el sistema interno del club, publicado al 1° de abril de 2026. En Campeonato y Premier se permite la participación de menores de 18 años con el hándicap requerido. Sin hándicap registrado, los profesionales podrán calcular uno con un mínimo de 8 scores entregados.", "notesText": ["Fecha límite de inscripción: domingo 19 de abril o al completarse el cupo de cada categoría.", "Fecha límite para cancelaciones con reembolso: martes 21 de abril. Después de esta fecha no se aceptan cancelaciones.", "Los jugadores que soliciten participar en una categoría que no corresponda a su hándicap tendrán que esperar hasta 2 días antes del inicio de juego de la categoría solicitada, para no desplazar a jugadores que sí cumplen con el hándicap requerido.", "Inscripciones — Asociados: a partir del miércoles 01 de abril.", "Inscripciones — Hijos de socios dependientes: a partir del miércoles 15 de abril.", "Inscripciones — Invitados e hijos no dependientes: a partir del domingo 19 de abril."], "inscripcionesText": "Cierre de inscripciones: domingo 19 de abril de 2026 (o antes si se completa el cupo de la categoría). Cancelaciones con reembolso hasta el martes 21 de abril."}', 2, 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  title        = VALUES(title),
  content      = VALUES(content),
  sort_order   = VALUES(sort_order),
  enabled      = VALUES(enabled);

INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled)
VALUES (346, 'costos', 'costos', 'Costos', '{"sociosPricing": [{"title": "Cuotas de inscripción", "tiers": [{"categoria": "Socios Titulares", "costo": "$6,000", "mayo6": "", "junio5": "", "julio4": "", "agosto3": "", "sept2": ""}, {"categoria": "Eméritos", "costo": "$5,000", "mayo6": "", "junio5": "", "julio4": "", "agosto3": "", "sept2": ""}, {"categoria": "Damas", "costo": "$5,000", "mayo6": "", "junio5": "", "julio4": "", "agosto3": "", "sept2": ""}, {"categoria": "Dependientes", "costo": "$5,000", "mayo6": "", "junio5": "", "julio4": "", "agosto3": "", "sept2": ""}, {"categoria": "Invitados Caballeros", "costo": "$18,500", "mayo6": "", "junio5": "", "julio4": "", "agosto3": "", "sept2": ""}, {"categoria": "Invitados Damas y Juveniles", "costo": "$10,500", "mayo6": "", "junio5": "", "julio4": "", "agosto3": "", "sept2": ""}]}], "foraneosPricing": [], "pricingNote": "Cuotas aplicables únicamente a jugadores que participen en el Torneo.", "contactInfo": {"clabe": "", "cuenta": "", "nombre": "", "bankName": ""}, "contactWarning": "", "inscripcionesText": "Cierre de inscripciones: domingo 19 de abril de 2026 (o antes si se completa el cupo). Cancelaciones con reembolso hasta el martes 21 de abril."}', 3, 1)
