INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled)
VALUES (346, 'premiacion', 'premiacion', 'Premiación', '{"items": [{"categoria": "Caballeros — Campeonato, Premier, AA, A, B, C y D", "premios": ["1°, 2° y 3° lugar (trofeos institucionales)."]}, {"categoria": "Seniors — Campeonato Mayores", "premios": ["1° y 2° Gross", "1° y 2° Neto"]}, {"categoria": "Seniors A y B", "premios": ["1°, 2° y 3° lugar de cada categoría."]}, {"categoria": "Damas A", "premios": ["1° y 2° Gross", "1°, 2° y 3° Neto"]}, {"categoria": "Damas B", "premios": ["1°, 2° y 3° Gross", "1°, 2° y 3° Neto"]}, {"categoria": "Damas C, D y E", "premios": ["1°, 2° y 3° lugar de cada categoría."]}, {"categoria": "Damas Estelares", "premios": ["1°, 2° y 3° lugar."]}]}', 5, 1)
