INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled)
VALUES (346, 'desempates', 'desempates', 'Desempates para Corte', '{"intro": "Lineamientos oficiales de desempate del LXX Torneo Anual Valle Alto 2026.", "paraCorte": ["Primer término: gana el jugador con mejor score del último día.", "Segundo término: comparación de tarjetas del último día por el sistema 9-6-3-1, de la vuelta del hoyo 10 al 18.", "Si persiste el empate, se aplica el mismo procedimiento para la 1ª vuelta (hoyos 1 al 9)."], "paraTrofeos": ["Solo para el 1er lugar en todas las categorías Gross o Neto: muerte súbita sin ventajas.", "El resto de los empates se define primero por el mejor score del último día.", "Si persiste el empate: comparación de tarjetas del último día (hoyo 10 al 18) bajo el sistema 9-6-3-1."], "nota": "Jugador que no pasó el corte oficialmente —una vez publicadas las listas de resultados— no podrá participar en la ronda final por ningún motivo. Para jugadores en dos categorías que pasen ambos cortes, deberán dar aviso al final aclarando en cuál de las dos jugarán la ronda final."}', 6, 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  title        = VALUES(title),
  content      = VALUES(content),
  sort_order   = VALUES(sort_order),
  enabled      = VALUES(enabled);

INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled)
VALUES (346, 'reglas', 'reglas', 'Reglas Locales', '{"items": [{"titulo": "Reglas Generales", "contenido": "Se jugará bajo las reglas de la USGA adoptadas por la Federación Mexicana de Golf, así como las reglas locales y términos de la competencia que se publicarán para el torneo. Las controversias sobre la aplicación de las reglas serán resueltas por el Oficial de Reglas y/o el Comité Organizador, cuyo fallo será definitivo e inapelable."}, {"titulo": "Ronda Estipulada", "contenido": "Las rondas de juego estipuladas para este torneo son de 9 hoyos."}, {"titulo": "Modificaciones por Clima", "contenido": "Si por cuestiones climatológicas no se logran jugar dos rondas de 18 hoyos, el Comité Organizador decidirá a cuántos hoyos se hará el corte."}, {"titulo": "Cupos por Categoría", "contenido": "Si una categoría alcanza el número máximo de jugadores se cerrará y los jugadores que se queden fuera entrarán en lista de espera. Si hay una cancelación o espacio disponible, se le llamará al jugador para inscribirse y formar parte del field."}, {"titulo": "Decisiones del Comité", "contenido": "El Comité Organizador se reserva el derecho de hacer cualquier cambio que juzgue necesario para el mejor desarrollo del torneo. Cualquier punto no previsto en la presente convocatoria, o que no esté redactado con claridad, será resuelto por el Comité Organizador y su decisión será inapelable."}], "reglamento": [{"titulo": "Caballeros — Campeonato, Premier y AA (Stroke Play sin hándicap)", "contenido": "54 hoyos. Corte a los 36 hoyos jugados. Pasan a la final los mejores 12 jugadores sin empates. Cupo limitado a 36 jugadores por categoría."}, {"titulo": "Caballeros — Categoría A (Stroke Play sin hándicap)", "contenido": "Edad 18 o más. 72 hoyos. Dos cortes: el primero a 36 hoyos (pasan los mejores 24 sin empates) y el segundo a 54 hoyos (pasan a la final los primeros 12 sin empates). Cupo limitado a 80 jugadores."}, {"titulo": "Caballeros — Categorías B, C y D (Stableford acumulado al 80% del hándicap)", "contenido": "Edad 18 o más. 72 hoyos. Dos cortes: el primero a 36 hoyos (pasan los mejores 24 sin empates) y el segundo a 54 hoyos (pasan a la final los primeros 12 sin empates). Cupos: B y C — 96 jugadores; D — 80 jugadores."}, {"titulo": "Seniors — Campeonato Mayores (Stroke Play al 80% del hándicap)", "contenido": "54 hoyos. Corte a los 36 hoyos. Pasan a la final los mejores 4 Gross y los mejores 4 Neto, sin empates. Edad mínima: 50 años cumplidos al primer día de juego. Juegan de marcas blancas. Si un jugador gana la final Gross y Neto, deberá llevarse únicamente el trofeo Gross. Cupo limitado a 16 jugadores."}, {"titulo": "Seniors — A y B (Stableford al 80% del hándicap)", "contenido": "54 hoyos. Corte a los 36 hoyos. Pasan los mejores 12 jugadores sin empates de cada categoría, conservando el acumulado de puntos. Edad mínima: 60 años cumplidos al primer día de juego. Juegan de marcas doradas. Las categorías se dividen según el H.I. de los inscritos. Cupo límite entre A y B: 56 jugadores."}, {"titulo": "Damas — A y B (Stroke Play al 80% del hándicap)", "contenido": "54 hoyos. Corte a los 36 hoyos. Pasan las mejores 4 Gross y las mejores 4 Neto sin empates. Si una jugadora pasa a la final Gross y también a la Neto, jugará únicamente por el trofeo Gross; en ese caso la quinta mejor jugadora Neto jugará por el trofeo Neto."}, {"titulo": "Damas — C, D y E (Stableford al 80% del hándicap)", "contenido": "54 hoyos. Corte a los 36 hoyos. Pasan las mejores 8 jugadoras sin empates conservando el acumulado de puntos. Cupo límite entre A, B, C, D y E: 100 jugadoras."}, {"titulo": "Damas Estelares", "contenido": "27 hoyos sin HCP. Corte a los 18 hoyos. Pasan las mejores 6 jugadoras sin empates conservando el acumulado de puntos. Cupo límite: 12 jugadoras."}, {"titulo": "Rangos de Hándicap — Caballeros (H.I.)", "contenido": "Campeonato: hasta 0.9.\\nPremier: 1.0 a 3.9.\\nAA: 4.0 a 7.0.\\nA: 7.1 a 11.3.\\nB: 11.4 a 15.8.\\nC: 15.9 a 21.2.\\nD: 21.3 a 28.4."}, {"titulo": "Rangos de Hándicap — Seniors (H.I.)", "contenido": "Campeonato Mayores: hasta 9.5.\\nA / B: 0 a 34.6 (la división A/B se hará entre los inscritos en base al H.I.)."}, {"titulo": "Rangos de Hándicap — Damas (H.I.)", "contenido": "A: hasta 13.5.\\nB: 13.6 a 17.9.\\nC: 18.0 a 22.3.\\nD: 22.4 a 27.6.\\nE: 27.7 a 35.5.\\nEstelares: sin HCP."}, {"titulo": "Marcas de Salida", "contenido": "Caballeros — Campeonato: Negras. Premier y AA: Azules. A, B, C y D: Blancas.\\nSeniors — Campeonato Mayores: Blancas. A y B: Doradas.\\nDamas — A, B, C, D y E: Rojas. Estelares: Naranjas."}, {"titulo": "Horarios de Salida", "contenido": "Salidas del turno matutino a partir de las 06:10 hrs. Salidas del turno vespertino a partir de las 11:00 hrs."}]}', 7, 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  title        = VALUES(title),
  content      = VALUES(content),
  sort_order   = VALUES(sort_order),
  enabled      = VALUES(enabled);

INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled)
VALUES (346, 'competencias', 'competencias', 'Competencias Especiales', '{"items": [{"titulo": "Tiro Espectacular de Approach", "descripcion": "Podrán participar únicamente jugadores inscritos al torneo. Cada participante tendrá derecho a realizar dos tiros en los días de calificación. Pasarán a la final los mejores 10 resultados diarios.", "fechas": "Calificación: sábado 25, domingo 26, lunes 27 y martes 28 de abril. Final: miércoles 29 de abril a partir de las 18:30 hrs.", "lugar": "Calificación en el área del par 3 (11:00 a 17:00 hrs). Final en el green del hoyo 15; presentarse 15 min antes en la terraza del Kiosco 10.", "premios": ["1er lugar: Auto 2026 (solo se entrega un auto).", "2do lugar: Bolsa de Golf."], "notas": "El orden de tiro en la final será según la distancia marcada en la calificación (de menor a mayor). El ganador del auto será el primer jugador que meta la pelota o quien la deje más cerca del hoyo; el ganador de la bolsa será el segundo en embocar o el segundo mejor O´yes."}, {"titulo": "Torneo de Putt y Putt de 35 yds", "descripcion": "Solo jugadores inscritos al torneo. Cada participante tendrá derecho a 2 tiros por día de calificación (una sola participación por día). Calificaciones del sábado 25 al miércoles 29 de abril, 11:00 a 17:00 hrs en el putting green.", "fechas": "Final: viernes 1 de mayo — 18:00 hrs Damas, 19:30 hrs Caballeros.", "lugar": "Putting green del Club y Putting Green de la Terraza (para el Putt Espectacular de 35 yds).", "premios": ["1er Lugar Damas: $10,000 en Vales de Back 9.", "1er Lugar Caballeros: $10,000 en Vales de Back 9.", "2do Lugar Damas: $7,000 en Vales de Back 9.", "2do Lugar Caballeros: $7,000 en Vales de Back 9.", "3er Lugar Damas: $5,000 en Vales de Back 9.", "3er Lugar Caballeros: $5,000 en Vales de Back 9.", "Putt Espectacular de 35 yds — Primer participante que emboque: 25,000 USD. Segundo que emboque o mejor O´yes: una bolsa de golf."], "notas": "Pasan a la final los mejores 64 caballeros (sábado, domingo y lunes: 14 por día; martes y miércoles: 11 por día) y las mejores 32 damas (sábado a martes: 7 por día; miércoles: 4). En empate de calificación gana el primer jugador que participó. En el Putt Espectacular participan las 4 finalistas damas y los 8 finalistas caballeros, con sorteo de turno y un solo tiro."}, {"titulo": "Torneo Driver Damas", "descripcion": "Driver de distancia: se premia el driver más largo dentro del área delimitada como fairway del hoyo 4, entre las categorías A, B, C, D y E. Driver de precisión: se premia el driver más cercano a la línea marcada en el fairway del hoyo 4, entre A, B, C, D, E y Estelares. Una jugadora no podrá ganar ambos premios.", "fechas": "Lunes 27 de abril, durante la primera ronda de juego de todas las categorías.", "lugar": "Hoyo 4.", "premios": ["1er lugar de precisión: 300 USD.", "1er lugar de distancia: 300 USD."], "notas": "Desempate de distancia: gana la bola más cerca de la línea de precisión. Desempate de precisión: gana la bola con mayor distancia."}, {"titulo": "Torneo Driver Caballeros", "descripcion": "Podrán participar todos los jugadores inscritos al torneo que tengan un mínimo de distancia de 280 yardas. Una sola categoría. Cada jugador tendrá derecho a 2 tiros; se medirá el más largo dentro del fairway. Gana quien logre mayor distancia dentro del fairway.", "fechas": "Jueves 30 de abril a las 18:30 hrs.", "lugar": "Tee del hoyo 16. Inscripciones el día del evento en la mesa de salida del hoyo 16.", "premios": ["1er lugar: 400 USD.", "2do lugar: 300 USD."], "notas": "En caso de empate, los jugadores tendrán derecho a 2 tiros adicionales; gana quien logre mejor distancia dentro del fairway. El ganador final tendrá derecho a 2 tiros adicionales para intentar mejorar su distancia."}, {"titulo": "Premios O´yes", "descripcion": "Reconocimientos especiales a los mejores tiros del torneo en greens y pares 3.", "fechas": "Durante todo el torneo (24 de abril al 02 de mayo de 2026).", "lugar": "Todos los pares 3 del campo.", "premios": ["Mejor O´yes general del día: Driver Ping modelo G440.", "Mejor O´yes de cada par 3 del día: Putter Scotty Cameron.", "Mejor O´yes general del torneo: Certificado de regalo Back9 por $50,000 MXN."], "notas": "Los resultados de O´yes pueden moverse hasta el último día del torneo."}]}', 8, 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  title        = VALUES(title),
  content      = VALUES(content),
  sort_order   = VALUES(sort_order),
  enabled      = VALUES(enabled);
